namespace Windose.Programs.Breeze
{
    public static class ControlTest
    {

        public static string data = "// Windose Control Test Suite\r\n// Tests all new GUI controls: ProgressBar, RadioButton, ComboBox, TabControl, Slider, Tooltip\r\n// Plus existing controls: Button, TextField, Checkbox, ListView, TreeView, etc.\r\n\r\nprocess(\"ControlTest\")\r\n\r\nlet win = window(\"Windose Control Test\", 50, 50, 700, 550)\r\nlet root = windowRoot(win)\r\n\r\n// ===== TAB CONTROL =====\r\nlet tabs = tabControl(\"\", 680, 480)\r\nadd(root, tabs)\r\n\r\n// ============================================================\r\n// TAB 1: Progress & Sliders\r\n// ============================================================\r\nlet tab1 = tabAdd(tabs, \"Progress & Sliders\")\r\nlet stack1 = stackPanel(\"vertical\")\r\nadd(tab1, stack1)\r\n\r\n// ProgressBar - determinate\r\nlet pLabel1 = panel(\"Determinate ProgressBar:\", 20)\r\nadd(stack1, pLabel1)\r\nlet progress1 = progressBar(\"\", 300, 25)\r\nadd(stack1, progress1)\r\n\r\n// ProgressBar - indeterminate\r\nlet pLabel2 = panel(\"Indeterminate ProgressBar:\", 20)\r\nadd(stack1, pLabel2)\r\nlet progress2 = progressBar(\"\", 300, 25)\r\nprogressIndeterminate(progress2, true)\r\nadd(stack1, progress2)\r\n\r\n// ProgressBar with text\r\nlet pLabel3 = panel(\"ProgressBar with text:\", 20)\r\nadd(stack1, pLabel3)\r\nlet progress3 = progressBar(\"Loading...\", 300, 25)\r\nset(progress3, \"fontSize\", 12)\r\nadd(stack1, progress3)\r\n\r\n// Slider - horizontal\r\nlet sLabel1 = panel(\"Horizontal Slider:\", 20)\r\nadd(stack1, sLabel1)\r\nlet slider1 = slider(\"Volume\", 300, 25)\r\nsliderRange(slider1, 0, 100)\r\nadd(stack1, slider1)\r\n\r\n// Slider - with value display\r\nlet sLabel2 = panel(\"Slider with ticks:\", 20)\r\nadd(stack1, sLabel2)\r\nlet slider2 = slider(\"Brightness\", 300, 25)\r\nsliderRange(slider2, 0, 255)\r\nset(slider2, \"showTicks\", true)\r\nadd(stack1, slider2)\r\n\r\n// ============================================================\r\n// TAB 2: Selection Controls\r\n// ============================================================\r\nlet tab2 = tabAdd(tabs, \"Selection Controls\")\r\nlet stack2 = stackPanel(\"vertical\")\r\nadd(tab2, stack2)\r\n\r\n// RadioButtons\r\nlet rbLabel = panel(\"RadioButton Group (Color):\", 20)\r\nadd(stack2, rbLabel)\r\n\r\nlet rbStack = stackPanel(\"horizontal\")\r\nadd(stack2, rbStack)\r\n\r\nlet rbRed = radioButton(\"Red\", \"color\")\r\nadd(rbStack, rbRed)\r\n\r\nlet rbGreen = radioButton(\"Green\", \"color\")\r\nadd(rbStack, rbGreen)\r\n\r\nlet rbBlue = radioButton(\"Blue\", \"color\")\r\nadd(rbStack, rbBlue)\r\n\r\n// Checkboxes\r\nlet cbLabel = panel(\"Checkboxes:\", 20)\r\nadd(stack2, cbLabel)\r\n\r\nlet cbStack = stackPanel(\"horizontal\")\r\nadd(stack2, cbStack)\r\n\r\nlet cb1 = checkbox(\"Option A\")\r\nadd(cbStack, cb1)\r\n\r\nlet cb2 = checkbox(\"Option B\")\r\nadd(cbStack, cb2)\r\n\r\nlet cb3 = checkbox(\"Option C\")\r\nadd(cbStack, cb3)\r\n\r\n// ComboBox\r\nlet comboLabel = panel(\"ComboBox (Font Selection):\", 20)\r\nadd(stack2, comboLabel)\r\n\r\nlet fontCombo = comboBox(\"Select Font\", 200)\r\ncomboAdd(fontCombo, \"Arial\")\r\ncomboAdd(fontCombo, \"Times New Roman\")\r\ncomboAdd(fontCombo, \"Courier New\")\r\ncomboAdd(fontCombo, \"Verdana\")\r\ncomboAdd(fontCombo, \"Segoe UI\")\r\nadd(stack2, fontCombo)\r\n\r\n// ============================================================\r\n// TAB 3: File & List Controls\r\n// ============================================================\r\nlet tab3 = tabAdd(tabs, \"File & List Controls\")\r\nlet stack3 = stackPanel(\"vertical\")\r\nadd(tab3, stack3)\r\n\r\n// ListView\r\nlet lvLabel = panel(\"ListView (icons mode):\", 20)\r\nadd(stack3, lvLabel)\r\n\r\nlet listView1 = listView(\"icons\")\r\nadd(stack3, listView1)\r\n\r\nlistItem(listView1, \"Documents\", \"/mnt/Documents\", true)\r\nlistItem(listView1, \"Pictures\", \"/mnt/Pictures\", true)\r\nlistItem(listView1, \"Music\", \"/mnt/Music\", true)\r\nlistItem(listView1, \"readme.txt\", \"/mnt/readme.txt\", false)\r\nlistItem(listView1, \"startup.breeze\", \"/mnt/startup.breeze\", false)\r\n\r\n// TreeView\r\nlet tvLabel = panel(\"TreeView:\", 20)\r\nadd(stack3, tvLabel)\r\n\r\nlet treeView1 = treeView()\r\nadd(stack3, treeView1)\r\n\r\nlet root1 = treeRoot(treeView1, \"My Computer\", \"computer\")\r\nlet driveC = treeChild(root1, \"Local Disk (C:)\", \"c:\")\r\ntreeChild(driveC, \"Windows\", \"c:\\\\windows\")\r\ntreeChild(driveC, \"Programs\", \"c:\\\\programs\")\r\nlet drive0 = treeChild(root1, \"System (/mnt)\", \"/mnt\")\r\ntreeChild(drive0, \"System\", \"/mnt/System\")\r\ntreeChild(drive0, \"Services\", \"/mnt/System/Services\")\r\n\r\n// ============================================================\r\n// TAB 4: Buttons & Actions\r\n// ============================================================\r\nlet tab4 = tabAdd(tabs, \"Buttons & Actions\")\r\nlet stack4 = stackPanel(\"vertical\")\r\nadd(tab4, stack4)\r\n\r\nlet actionLabel = panel(\"Action Buttons:\", 20)\r\nadd(stack4, actionLabel)\r\n\r\n// Progress control buttons\r\nlet btnStack1 = stackPanel(\"horizontal\")\r\nadd(stack4, btnStack1)\r\n\r\nlet btnInc = button(\"+10% Progress\", 120, 30)\r\nadd(btnStack1, btnInc)\r\n\r\nlet btnDec = button(\"-10% Progress\", 120, 30)\r\nadd(btnStack1, btnDec)\r\n\r\nlet btnReset = button(\"Reset\", 80, 30)\r\nadd(btnStack1, btnReset)\r\n\r\n// Slider control buttons\r\nlet btnStack2 = stackPanel(\"horizontal\")\r\nadd(stack4, btnStack2)\r\n\r\nlet btnSliderUp = button(\"Slider +10\", 100, 30)\r\nadd(btnStack2, btnSliderUp)\r\n\r\nlet btnSliderDown = button(\"Slider -10\", 100, 30)\r\nadd(btnStack2, btnSliderDown)\r\n\r\n// Combo control buttons\r\nlet btnStack3 = stackPanel(\"horizontal\")\r\nadd(stack4, btnStack3)\r\n\r\nlet btnComboGet = button(\"Get Combo Selection\", 160, 30)\r\nadd(btnStack3, btnComboGet)\r\n\r\nlet btnRadioGet = button(\"Get Radio Selection\", 160, 30)\r\nadd(btnStack3, btnRadioGet)\r\n\r\n// Status display\r\nlet statusLabel = panel(\"Status:\", 20)\r\nadd(stack4, statusLabel)\r\n\r\nlet statusField = textField(\"Ready\", 30)\r\nset(statusField, \"width\", 400)\r\nadd(stack4, statusField)\r\n\r\n// ============================================================\r\n// TAB 5: Tooltip Demo\r\n// ============================================================\r\nlet tab5 = tabAdd(tabs, \"Tooltip Demo\")\r\nlet stack5 = stackPanel(\"vertical\")\r\nadd(tab5, stack5)\r\n\r\nlet tipLabel = panel(\"Hover over these buttons to see tooltips:\", 20)\r\nadd(stack5, tipLabel)\r\n\r\nlet tip = tooltip()\r\n\r\nlet tipStack = stackPanel(\"horizontal\")\r\nadd(stack5, tipStack)\r\n\r\nlet btnSave = button(\"Save\", 100, 30)\r\ntooltipAttach(tip, btnSave, \"Saves the current document (Ctrl+S)\")\r\nadd(tipStack, btnSave)\r\n\r\nlet btnOpen = button(\"Open\", 100, 30)\r\ntooltipAttach(tip, btnOpen, \"Opens an existing file (Ctrl+O)\")\r\nadd(tipStack, btnOpen)\r\n\r\nlet btnPrint = button(\"Print\", 100, 30)\r\ntooltipAttach(tip, btnPrint, \"Prints the current document (Ctrl+P)\")\r\nadd(tipStack, btnPrint)\r\n\r\nlet btnDelete = button(\"Delete\", 100, 30)\r\ntooltipAttach(tip, btnDelete, \"Permanently deletes the selected item\")\r\nadd(tipStack, btnDelete)\r\n\r\nlet tipNote = panel(\"Tooltips appear after hovering for 500ms\", 20)\r\nadd(stack5, tipNote)\r\n\r\n// ============================================================\r\n// EVENT HANDLERS\r\n// ============================================================\r\n\r\n// ProgressBar buttons\r\non btnInc \"click\" => {\r\n    let current = value(progress1, \"value\")\r\n    if current < 100 {\r\n        progressValue(progress1, current + 10)\r\n        set(progress3, \"text\", \"Loading... \" + (current + 10) + \"%\")\r\n    }\r\n    set(statusField, \"text\", \"Progress increased to \" + (current + 10) + \"%\")\r\n}\r\n\r\non btnDec \"click\" => {\r\n    let current = value(progress1, \"value\")\r\n    if current > 0 {\r\n        progressValue(progress1, current - 10)\r\n        set(progress3, \"text\", \"Loading... \" + (current - 10) + \"%\")\r\n    }\r\n    set(statusField, \"text\", \"Progress decreased to \" + (current - 10) + \"%\")\r\n}\r\n\r\non btnReset \"click\" => {\r\n    progressValue(progress1, 0)\r\n    set(progress3, \"text\", \"Loading... 0%\")\r\n    set(statusField, \"text\", \"Progress reset to 0%\")\r\n}\r\n\r\n// Slider buttons\r\non btnSliderUp \"click\" => {\r\n    let current = value(slider1, \"value\")\r\n    sliderValue(slider1, current + 10)\r\n    set(statusField, \"text\", \"Slider set to \" + (current + 10))\r\n}\r\n\r\non btnSliderDown \"click\" => {\r\n    let current = value(slider1, \"value\")\r\n    sliderValue(slider1, current - 10)\r\n    set(statusField, \"text\", \"Slider set to \" + (current - 10))\r\n}\r\n\r\n// Combo button\r\non btnComboGet \"click\" => {\r\n    let selected = comboText(fontCombo)\r\n    let index = comboSelected(fontCombo)\r\n    if selected != \"\" {\r\n        set(statusField, \"text\", \"Selected font: \" + selected + \" (index \" + index + \")\")\r\n    } else {\r\n        set(statusField, \"text\", \"No font selected\")\r\n    }\r\n}\r\n\r\n// Radio button\r\non btnRadioGet \"click\" => {\r\n    let redChecked = radioChecked(rbRed)\r\n    let greenChecked = radioChecked(rbGreen)\r\n    let blueChecked = radioChecked(rbBlue)\r\n\r\n    if redChecked {\r\n        set(statusField, \"text\", \"Selected color: Red\")\r\n    } else if greenChecked {\r\n        set(statusField, \"text\", \"Selected color: Green\")\r\n    } else if blueChecked {\r\n        set(statusField, \"text\", \"Selected color: Blue\")\r\n    } else {\r\n        set(statusField, \"text\", \"No color selected\")\r\n    }\r\n}\r\n\r\n// Slider value changed\r\non slider1 \"change\" => {\r\n    let val = value(slider1, \"value\")\r\n    set(statusField, \"text\", \"Slider value: \" + val)\r\n}\r\n\r\n// Combo selection changed\r\non fontCombo \"change\" => {\r\n    let selected = comboText(fontCombo)\r\n    set(statusField, \"text\", \"Font changed to: \" + selected)\r\n}\r\n\r\n// Radio button changes\r\non rbRed \"change\" => {\r\n    set(statusField, \"text\", \"Color changed to Red\")\r\n}\r\n\r\non rbGreen \"change\" => {\r\n    set(statusField, \"text\", \"Color changed to Green\")\r\n}\r\n\r\non rbBlue \"change\" => {\r\n    set(statusField, \"text\", \"Color changed to Blue\")\r\n}\r\n\r\n// ListView selection\r\non listView1 \"select\" => {\r\n    let item = value(event, \"text\")\r\n    let path = value(event, \"path\")\r\n    set(statusField, \"text\", \"Selected: \" + item + \" (\" + path + \")\")\r\n}\r\n\r\n// TreeView selection\r\non treeView1 \"select\" => {\r\n    let item = value(event, \"text\")\r\n    set(statusField, \"text\", \"Tree selected: \" + item)\r\n}\r\n\r\n// ============================================================\r\n// TIMER: Auto-animate the indeterminate progress bar\r\n// ============================================================\r\nlet animTimer = timer(100)\r\non animTimer \"tick\" => {\r\n    // Auto-increment the determinate progress bar in a loop\r\n    let current = value(progress1, \"value\")\r\n    if current >= 100 {\r\n        progressValue(progress1, 0)\r\n    } else {\r\n        progressValue(progress1, current + 1)\r\n    }\r\n    set(progress3, \"text\", \"Loading... \" + (current + 1) + \"%\")\r\n}\r\nstartTimer(animTimer)\r\n\r\n// Show the window\r\nshow(win)";
    }
}
